// work is hidden behind pt_metal_host.hpp, so this file is plain C++.
#include <algorithm>
#include <chrono>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <string>
#include <vector>

#include <libgen.h>

#include "pt_bvh.hpp"
#include "pt_gpu_types.hpp"
#include "pt_image.hpp"
#include "pt_metal_host.hpp"
#include "pt_mesh.hpp"
#include "pt_scene.hpp"

namespace {

struct Options {
    std::string mesh =
        "/Users/peihongguo/Code/aos/reports/rasterizer-bunny/assets/stanford-bunny.obj";
    std::string scene_config;
    std::string out = "output.ppm";
    std::string out_pfm = "output.pfm";
    int spp = 0;        // 0 means "use the scene value"
    int benchmark = 0;  // 0 means "single frame, no benchmark line"
    int threads = 4;
    unsigned int seed = 1;
};

void print_usage() {
    std::printf("usage: pathtracer [--mesh p] [--scene-config p] [--spp n] [--seed n]\n");
    std::printf("                  [--out p] [--out-pfm p] [--benchmark n] [--threads n]\n");
}

bool take_value(int argc, char** argv, int& index, std::string& destination) {
    if (index + 1 >= argc) {
        std::fprintf(stderr, "missing value for %s\n", argv[index]);
        return false;
    }
    destination = argv[++index];
    return true;
}

bool parse_options(int argc, char** argv, Options& options) {
    for (int i = 1; i < argc; ++i) {
        std::string value;
        const std::string argument = argv[i];
        if (argument == "--mesh") {
            if (!take_value(argc, argv, i, options.mesh)) {
                return false;
            }
        } else if (argument == "--scene-config") {
            if (!take_value(argc, argv, i, options.scene_config)) {
                return false;
            }
        } else if (argument == "--out") {
            if (!take_value(argc, argv, i, options.out)) {
                return false;
            }
        } else if (argument == "--out-pfm") {
            if (!take_value(argc, argv, i, options.out_pfm)) {
                return false;
            }
        } else if (argument == "--spp") {
            if (!take_value(argc, argv, i, value)) {
                return false;
            }
            options.spp = std::atoi(value.c_str());
        } else if (argument == "--seed") {
            if (!take_value(argc, argv, i, value)) {
                return false;
            }
            options.seed = static_cast<unsigned int>(std::strtoul(value.c_str(), nullptr, 10));
        } else if (argument == "--benchmark") {
            if (!take_value(argc, argv, i, value)) {
                return false;
            }
            options.benchmark = std::atoi(value.c_str());
        } else if (argument == "--threads") {
            if (!take_value(argc, argv, i, value)) {
                return false;
            }
            options.threads = std::atoi(value.c_str());
        } else if (argument == "--help" || argument == "-h") {
            print_usage();
            std::exit(0);
        } else {
            std::fprintf(stderr, "unknown argument: %s\n", argument.c_str());
            return false;
        }
    }
    // The task caps host CPU work at 8 threads.
    options.threads = std::max(1, std::min(8, options.threads));
    return true;
}

// Directory holding the executable so the .metal sources can be found next to
// it, whatever the current working directory is.
std::string executable_directory(const std::string& argv0) {
    if (argv0.find('/') == std::string::npos) {
        return std::string(".");
    }
    return argv0.substr(0, argv0.find_last_of('/'));
}

double milliseconds(std::chrono::steady_clock::duration d) {
    return std::chrono::duration<double, std::milli>(d).count();
}

}  // namespace

int main(int argc, char** argv) {
    Options options;
    if (!parse_options(argc, argv, options)) {
        print_usage();
        return 1;
    }

    pt::Scene scene;
    std::string error;
    if (!options.scene_config.empty()) {
        if (!pt::load_scene_config(options.scene_config, scene, error)) {
            std::fprintf(stderr, "scene error: %s\n", error.c_str());
            return 1;
        }
    }
    const int spp = options.spp > 0 ? options.spp : scene.spp;
    const int width = scene.width;
    const int height = scene.height;

    // ---- Work that is allowed outside the timed region -------------------
    const auto setup_start = std::chrono::steady_clock::now();
    pt::Mesh mesh;
    if (!pt::load_obj_mesh(options.mesh, mesh, error)) {
        std::fprintf(stderr, "mesh error: %s\n", error.c_str());
        return 1;
    }
    // Normalise the bunny: chosen height, base on the floor, centred.
    pt::transform_mesh(mesh, scene.bunny_scale, scene.bunny_translate);
    pt::Bvh bvh;
    pt::build_bvh(mesh, bvh);

    pt::MetalPathTracer tracer;
    const std::string exec_dir = executable_directory(argv[0]);
    const std::string shader_dir = exec_dir + "/shaders";
    const std::string shared_header = exec_dir + "/include/pt_gpu_types.hpp";
    if (!tracer.init(shader_dir, shared_header, error)) {
        std::fprintf(stderr, "metal init error: %s\n", error.c_str());
        return 1;
    }

    const pt::GpuMeshData mesh_data{mesh.vertices.data(),
                                    mesh.vertices.size(),
                                    mesh.triangles.data(),
                                    mesh.triangles.size(),
                                    bvh.nodes.data(),
                                    bvh.nodes.size(),
                                    bvh.triangle_order.data(),
                                    bvh.triangle_order.size()};
    if (!tracer.upload_mesh(mesh_data, error)) {
        std::fprintf(stderr, "mesh upload error: %s\n", error.c_str());
        return 1;
    }
    if (!tracer.allocate(width, height, error)) {
        std::fprintf(stderr, "allocation error: %s\n", error.c_str());
        return 1;
    }
    const double setup_ms = milliseconds(std::chrono::steady_clock::now() - setup_start);

    PtParams params;
    pt::fill_params(scene, params, width, height, spp, options.seed);

    // ---- Timed region: dispatch, GPU execution, wait, tone map, readback --
    std::vector<float> radiance;
    std::vector<unsigned char> image;
    unsigned int samples = 0;
    double gpu_ms = 0.0;

    const int frames = options.benchmark > 0 ? options.benchmark : 1;
    double best_ms = 1e300;
    double best_gpu_ms = 1e300;
    double total_ms = 0.0;

    for (int frame = 0; frame < frames; ++frame) {
        const auto frame_start = std::chrono::steady_clock::now();
        if (!tracer.render_frame(params, radiance, image, samples, gpu_ms, error)) {
            std::fprintf(stderr, "render error: %s\n", error.c_str());
            return 1;
        }
        const double frame_ms = milliseconds(std::chrono::steady_clock::now() - frame_start);
        best_ms = std::min(best_ms, frame_ms);
        best_gpu_ms = std::min(best_gpu_ms, gpu_ms);
        total_ms += frame_ms;
    }

    if (options.benchmark > 0) {
        std::printf("render_ms_best=%.3f render_ms_avg=%.3f gpu_ms_best=%.3f spp=%d width=%d "
                    "height=%d samples=%u threads_used=%d\n",
                    best_ms, total_ms / static_cast<double>(frames), best_gpu_ms, spp, width,
                    height, samples, options.threads);
        std::fflush(stdout);
    }

    // The trace kernel writes float4 and the tone mapper uchar4; both are
    // repacked into the 3-channel formats the outputs require.
    const size_t pixels = static_cast<size_t>(width) * static_cast<size_t>(height);
    std::vector<unsigned char> rgb(pixels * 3);
    for (size_t pixel = 0; pixel < pixels; ++pixel) {
        for (int channel = 0; channel < 3; ++channel) {
            rgb[pixel * 3 + channel] = image[pixel * 4 + channel];
        }
    }
    if (!pt::write_ppm(options.out, rgb, width, height, error)) {
        std::fprintf(stderr, "ppm error: %s\n", error.c_str());
        return 1;
    }
    if (!options.out_pfm.empty()) {
        std::vector<float> linear(pixels * 3);
        for (size_t pixel = 0; pixel < pixels; ++pixel) {
            for (int channel = 0; channel < 3; ++channel) {
                linear[pixel * 3 + channel] = radiance[pixel * 4 + channel];
            }
        }
        if (!pt::write_pfm(options.out_pfm, linear, width, height, error)) {
            std::fprintf(stderr, "pfm error: %s\n", error.c_str());
            return 1;
        }
    }

    if (options.benchmark <= 0) {
        std::printf("setup_ms=%.1f samples=%u width=%d height=%d spp=%d threads_used=%d "
                    "triangles=%zu bvh_nodes=%zu\n",
                    setup_ms, samples, width, height, spp, options.threads,
                    mesh.triangles.size() / 3, bvh.nodes.size());
    }
    return 0;
}
