#pragma once

// Maximum depth of the per-thread BVH traversal stack. The host build refuses
// to make the tree deeper than PT_BVH_MAX_DEPTH, and a near-first walk pushes
// at most one node per level, so this stack can never overflow.
#define PT_BVH_STACK_SIZE 20
#define PT_BVH_MAX_DEPTH 16

// High bit of PtBvhNode::b marks a leaf; the low bits hold the triangle count.
#define PT_BVH_LEAF_BIT 0x80000000u

// One mesh vertex: position and geometric normal, world space. Host-only: the
// GPU reads the packed triangle tables below instead.
struct PtVertex {
    float position[3];
    float normal[3];
};

// One BVH node, exactly 32 bytes: half the traffic of the round-1 40-byte
// layout, and four nodes fit in one 128-byte cache line. The tree is stored in
// pre-order, so an internal node's left child is `index + 1` and only the
// right child index needs storing. `b` holds the escape link used by the
// stackless traversal (the node to visit once this subtree is done) and its
// high bit is the leaf flag; a leaf stores its triangle range in `a` as
// (start << 3) | count, while an internal node stores the right child index.
struct PtBvhNode {
    float bmin[3];
    float bmax[3];
    unsigned int a;
    unsigned int b;
};

// One triangle as an origin plus two edge vectors (36 bytes), precomputed on
// the host. This removes the vertex-index indirection and two subtractions
// from the hot intersection test, and a leaf's triangles are contiguous so one
// leaf costs a couple of wide loads instead of twelve scattered ones.
struct PtTri {
    float origin[3];
    float edge1[3];
    float edge2[3];
};

// The three vertex normals of one triangle (36 bytes), kept in a separate
// table because they are only needed when a triangle wins the nearest-hit
// test; shadow and any-hit rays never touch this memory.
struct PtTriNormals {
    float n0[3];
    float n1[3];
    float n2[3];
