// Bound as a `constant` buffer so the GPU reads it through the uniform path.
struct PtParams {
    float camera_position[3];
    float camera_target[3];
    float camera_up[3];
    float camera_right[3];   // orthonormal basis, computed on the host
    float camera_forward[3];
    float camera_scale_x;    // image plane extent for the aspect ratio
    float camera_scale_y;
    float vertical_fov_deg;
    float ior;
    float floor_height;
    float floor_albedo;
    float env_radiance[3];
