// intersection for the megakernel path tracer.
//
// The BVH is stored in pre-order with 32-byte nodes: an internal node's left
// child is `index + 1` and `a` holds the right child, while a leaf sets the
// high bit of `b` and stores its triangle range in the packed triangle table.
// Traversal keeps a short stack of right children; because the host build caps
// the tree at PT_BVH_MAX_DEPTH levels, PT_BVH_STACK_SIZE entries are enough.
// The host prepends <metal_stdlib> and pt_gpu_types.hpp before compiling, so
// only kernel code appears here.

// ---------------------------------------------------------------------------
// Deterministic RNG (PCG-XSH) and small helpers.
// ---------------------------------------------------------------------------

inline uint pt_pcg_next(thread uint& state) {
    state = state * 747796405u + 2891336453u;
    const uint word = ((state >> ((state >> 28u) + 4u)) ^ state) * 277803737u;
    return (word >> 22u) ^ word;
}

inline float pt_random(thread uint& state) {
    return float(pt_pcg_next(state)) * (1.0 / 4294967296.0);
}

// Per-pixel, per-sample stream seed: a pure function of (seed, pixel, sample).
inline uint pt_seed_pixel(uint seed, uint pixel, uint sample) {
    uint state = seed * 747796405u + pixel * 2654435761u + sample * 1597334677u;
    return pt_pcg_next(state);
}

inline float3 pt_v3(device const float* a) {
    return float3(a[0], a[1], a[2]);
}

inline float3 pt_v3(constant const float* a) {
    return float3(a[0], a[1], a[2]);
}

inline float3 pt_orthonormal_tangent(float3 n) {
    // Duff et al. branchless tangent frame construction.
    const float sign = copysign(1.0f, n.z);
    const float a = -1.0f / (sign + n.z);
    const float b = n.x * n.y * a;
    return float3(1.0f + sign * a * n.x * n.x, sign * b, -sign * n.x);
}

// ---------------------------------------------------------------------------
// Ray and intersection structures.
// ---------------------------------------------------------------------------

struct PtRay {
    float3 origin;
    float3 direction;
    float3 inv_direction;
};

inline PtRay pt_make_ray(float3 origin, float3 direction) {
    PtRay ray;
    ray.origin = origin;
    ray.direction = direction;
    ray.inv_direction = float3(1.0f / direction.x, 1.0f / direction.y, 1.0f / direction.z);
    return ray;
}

enum PtMaterial {
    PtMaterialNone = 0,
    PtMaterialFloor = 1,
    PtMaterialLight = 2,
    PtMaterialGlass = 3
};

struct PtHit {
    float t;
    uint material;
    float3 normal;
    float3 position;
};

struct PtScene {
    constant PtParams* params;
    device const PtBvhNode* nodes;
    device const PtTri* triangles;
    device const PtTriNormals* normals;
};

// Ray/axis-aligned box slab test using the precomputed inverse direction.
inline bool pt_ray_aabb(device const PtBvhNode& node, float3 origin, float3 inv_direction,
                        float t_min, float t_max) {
    const float3 bmin = pt_v3(node.bmin);
    const float3 bmax = pt_v3(node.bmax);
    const float3 t0 = (bmin - origin) * inv_direction;
    const float3 t1 = (bmax - origin) * inv_direction;
    const float3 lower = fmin(t0, t1);
    const float3 upper = fmax(t0, t1);
    const float entered = fmax(fmax(lower.x, lower.y), max(lower.z, t_min));
    const float exited = fmin(fmin(upper.x, upper.y), min(upper.z, t_max));
    return entered <= exited && exited > 0.0f;
}

// Same slab test, but also reports where the ray leaves the box. Used on the
// root node so the rest of the traversal can prune against the model's exit
// distance instead of an open-ended t_max.
inline bool pt_ray_aabb_exit(device const PtBvhNode& node, float3 origin, float3 inv_direction,
                             float t_min, float t_max, thread float& exited_out) {
    const float3 bmin = pt_v3(node.bmin);
    const float3 bmax = pt_v3(node.bmax);
    const float3 t0 = (bmin - origin) * inv_direction;
    const float3 t1 = (bmax - origin) * inv_direction;
    const float3 lower = fmin(t0, t1);
    const float3 upper = fmax(t0, t1);
    const float entered = fmax(fmax(lower.x, lower.y), max(lower.z, t_min));
    const float exited = fmin(fmin(upper.x, upper.y), min(upper.z, t_max));
    exited_out = exited;
    return entered <= exited && exited > 0.0f;
}

// Moller-Trumbore against the precomputed origin/edge1/edge2 form, double
// sided because the glass shows backfaces.
inline bool pt_ray_triangle(device const PtTri& tri, float3 origin, float3 direction,
                            thread float& t, thread float& u, thread float& v) {
    const float3 e1 = pt_v3(tri.edge1);
    const float3 e2 = pt_v3(tri.edge2);
    const float3 p = cross(direction, e2);
    const float det = dot(e1, p);
    if (fabs(det) < 1e-12f) {
        return false;
    }
    const float inv_det = 1.0f / det;
    const float3 s = origin - pt_v3(tri.origin);
    u = dot(s, p) * inv_det;
    if (u < 0.0f || u > 1.0f) {
        return false;
    }
    const float3 q = cross(s, e1);
    v = dot(direction, q) * inv_det;
    if (v < 0.0f || u + v > 1.0f) {
        return false;
    }
    t = dot(e2, q) * inv_det;
    return t > 1e-5f;
}

inline bool pt_ray_plane_y(float3 origin, float3 direction, float height, thread float& t) {
    if (fabs(direction.y) < 1e-9f) {
        return false;
    }
    t = (height - origin.y) / direction.y;
    return t > 1e-4f;
}

// Rectangle spanned by light_u/light_v around light_center, seen only from the
// emission side (a one-sided emitter).
inline bool pt_ray_light_rect(constant PtParams& params, float3 origin, float3 direction,
                              thread float& t, thread float3& point) {
    const float3 normal = pt_v3(params.light_normal);
    const float denom = dot(direction, normal);
    if (denom > -1e-9f) {
        return false;
    }
    const float3 center = pt_v3(params.light_center);
    const float candidate = dot(center - origin, normal) / denom;
    if (candidate <= 1e-4f) {
        return false;
    }
    const float3 hit_point = origin + candidate * direction;
    const float3 delta = hit_point - center;
    const float su = dot(delta, pt_v3(params.light_u));
    const float sv = dot(delta, pt_v3(params.light_v));
    if (fabs(su) > params.light_half_u || fabs(sv) > params.light_half_v) {
        return false;
    }
    t = candidate;
    point = hit_point;
    return true;
}

// Nearest-hit BVH traversal. Normals are fetched only when a triangle wins, so
// losing triangles cost nothing beyond the intersection test itself.
inline bool pt_intersect_mesh(PtScene scene, PtRay ray, thread float& best_t,
                              thread float3& best_normal) {
    uint stack[PT_BVH_STACK_SIZE];
    int stack_size = 0;
    uint node_index = 0;
    bool found = false;

    while (true) {
        device const PtBvhNode& node = scene.nodes[node_index];
        if (pt_ray_aabb(node, ray.origin, ray.inv_direction, 1e-4f, best_t)) {
            if (node.b & PT_BVH_LEAF_BIT) {
                const uint start = node.a;
                const uint count = node.b & 0x7FFFFFFFu;
                for (uint i = 0; i < count; ++i) {
                    const uint slot = start + i;
                    float t = 0.0f;
                    float u = 0.0f;
                    float v = 0.0f;
                    if (pt_ray_triangle(scene.triangles[slot], ray.origin, ray.direction, t, u,
                                        v) &&
                        t < best_t) {
                        best_t = t;
                        const device PtTriNormals& nrm = scene.normals[slot];
                        best_normal = normalize((1.0f - u - v) * pt_v3(nrm.n0) +
                                                u * pt_v3(nrm.n1) + v * pt_v3(nrm.n2));
                        found = true;
                    }
                }
            } else if (stack_size < PT_BVH_STACK_SIZE) {
                // Pre-order layout: the left child is the next slot, so only
                // the right child has to be remembered.
                stack[stack_size++] = node.a;
                node_index = node_index + 1u;
                continue;
            }
        }
        if (stack_size == 0) {
            break;
        }
        node_index = stack[--stack_size];
    }
    return found;
}

// Any-hit traversal for shadow rays: no floor or emitter test, no normals, and
// it returns as soon as one triangle is hit. The emitter sits above the floor
// and shadow rays start on the floor pointing at it, so the floor plane can
// never occlude them and skipping that test is exact.
inline bool pt_shadow_hit(PtScene scene, PtRay ray, float t_limit) {
    uint stack[PT_BVH_STACK_SIZE];
    int stack_size = 0;
    uint node_index = 0;

    while (true) {
        device const PtBvhNode& node = scene.nodes[node_index];
        if (pt_ray_aabb(node, ray.origin, ray.inv_direction, 1e-4f, t_limit)) {
            if (node.b & PT_BVH_LEAF_BIT) {
                const uint start = node.a;
                const uint count = node.b & 0x7FFFFFFFu;
                for (uint i = 0; i < count; ++i) {
                    float t = 0.0f;
                    float u = 0.0f;
                    float v = 0.0f;
                    if (pt_ray_triangle(scene.triangles[start + i], ray.origin, ray.direction, t,
                                        u, v) &&
                        t < t_limit) {
                        return true;
                    }
                }
            } else if (stack_size < PT_BVH_STACK_SIZE) {
                stack[stack_size++] = node.a;
                node_index = node_index + 1u;
                continue;
            }
        }
        if (stack_size == 0) {
            break;
        }
        node_index = stack[--stack_size];
    }
    return false;
}

// Closest hit over floor plane, one-sided emitter and mesh.
inline PtHit pt_intersect_scene(PtScene scene, PtRay ray) {
    PtHit hit;
    hit.t = 1e30f;
    hit.material = PtMaterialNone;
    hit.normal = float3(0.0f, 1.0f, 0.0f);
    hit.position = float3(0.0f);

    float t_floor = 0.0f;
    if (pt_ray_plane_y(ray.origin, ray.direction, scene.params->floor_height, t_floor) &&
        t_floor < hit.t) {
        hit.t = t_floor;
        hit.material = PtMaterialFloor;
        hit.normal = float3(0.0f, 1.0f, 0.0f);
        hit.position = ray.origin + t_floor * ray.direction;
    }

    float t_light = 0.0f;
    float3 light_point = float3(0.0f);
    if (pt_ray_light_rect(*scene.params, ray.origin, ray.direction, t_light, light_point) &&
        t_light < hit.t) {
        hit.t = t_light;
        hit.material = PtMaterialLight;
        hit.normal = pt_v3(scene.params->light_normal);
        hit.position = light_point;
    }

    float3 mesh_normal = float3(0.0f, 1.0f, 0.0f);
    float mesh_t = hit.t;
    if (pt_intersect_mesh(scene, ray, mesh_t, mesh_normal)) {
        hit.t = mesh_t;
        hit.material = PtMaterialGlass;
        hit.normal = mesh_normal;
        hit.position = ray.origin + mesh_t * ray.direction;
    }
    return hit;
}

// Shadow test: the bunny is the only possible occluder of the emitter.
inline bool pt_occluded(PtScene scene, PtRay ray, float t_limit) {
    return pt_shadow_hit(scene, ray, t_limit - 1e-3f);
}
