    const float3 q = cross(s, e1);
    v = dot(direction, q) * inv_det;
    if (v < 0.0f || u + v > 1.0f) {
        return false;
    }
    t = dot(e2, q) * inv_det;
    return t > 1e-5f;
}

inline bool pt_ray_plane_y(float3 origin, float3 direction, float height, thread float& t) {
    if (fabs(direction.y) < 1e-9f) {
        return false;
    }
    t = (height - origin.y) / direction.y;
    return t > 1e-4f;
}

// Rectangle spanned by light_u/light_v around light_center, seen only from the
// emission side (a one-sided emitter).
inline bool pt_ray_light_rect(constant PtParams& params, float3 origin, float3 direction,
                              thread float& t, thread float3& point) {
    const float3 normal = pt_v3(params.light_normal);
    const float denom = dot(direction, normal);
    if (denom > -1e-9f) {
        return false;
    }
    const float3 center = pt_v3(params.light_center);
    const float candidate = dot(center - origin, normal) / denom;
    if (candidate <= 1e-4f) {
        return false;
    }
    const float3 hit_point = origin + candidate * direction;
    const float3 delta = hit_point - center;
    const float su = dot(delta, pt_v3(params.light_u));
    const float sv = dot(delta, pt_v3(params.light_v));
    if (fabs(su) > params.light_half_u || fabs(sv) > params.light_half_v) {
        return false;
    }
    t = candidate;
    point = hit_point;
    return true;
}

// Nearest-hit BVH traversal. Normals are fetched only when a triangle wins, so
// losing triangles cost nothing beyond the intersection test itself.
//
// The loop tracks whether the current node was already tested by its parent:
// when the child selection below proves a child is hit, descending into it must
// not repeat that slab test. Deferred children are pushed WITH their entered
// distance. A node that was hit when pushed stays intersected by the ray (its
// entered/exited interval is fixed and entered >= t_min > 0), so the only thing
// that can invalidate it later is the near-hit limit tightening to best_t; the
// pop-time slab test therefore reduces to the single compare
// `entered <= best_t`. Pruned subtrees are dropped without touching memory at
// all and surviving pops load only their 4-byte payload. This visits exactly
// the same triangles as re-running the full test, so the hit is identical.
inline bool pt_intersect_mesh(PtScene scene, PtRay ray, thread float& best_t,
                              thread float3& best_normal) {
    const float t_min_q = 1e-4f;
    float t_max_q = best_t;
    const PtQRay q = pt_make_qray(scene, ray, t_min_q, t_max_q);
    uint stack[PT_BVH_STACK_SIZE];
    float stack_entered[PT_BVH_STACK_SIZE];
    // The pushed child's payload is carried as well: the parent already loaded
    // it to test the child's box, so the pop path needs no global load at all
    // before it can branch on leaf/internal and form the child addresses.
    uint stack_payload[PT_BVH_STACK_SIZE];
    int stack_size = 0;
    uint node_index = 0;
    bool node_tested = false;
    // The winning triangle is recorded as (slot, u, v) and its shading normal is
    // interpolated once, after the walk. Keeping the float3 normal and the
    // dependent normals-table load out of the loop body takes three live
    // registers and one memory fetch off the hot traversal path; the winner, and
    // therefore the normal, is unchanged.
    uint best_slot = 0xFFFFFFFFu;
    float best_u = 0.0f;
    float best_v = 0.0f;
    // Payload of the current node. It is only read when the node arrived here
    // already hit-tested by its parent, and in that case the parent had to load
    // this very node to test its box, so it can hand the payload over for free
    // and the descent loads nothing. Only one register is carried across the
    // loop; carrying the whole 16-byte node measured slower (register pressure).
    uint payload = 0u;

    while (true) {
        if (!node_tested) {
            // Only the root arrives untested: every other visit either inherits
            // a tested child's payload or passes the entered-distance check.
            const uint4 raw = scene.nodes[node_index];
            payload = raw.w;
            if (!pt_qbox_hit(pt_decode_box(raw), q.inv_direction, q.origin_times_inv, q.t_min,
                             t_max_q)) {
                break;
            }
        }
        node_tested = false;

        if (pt_node_is_leaf(payload)) {
            const uint start = pt_node_start(payload);
            const uint count = pt_node_count(payload);
            for (uint i = 0; i < count; ++i) {
                const uint slot = start + i;
                float t = 0.0f;
                float u = 0.0f;
                float v = 0.0f;
                if (pt_ray_triangle(scene.triangles[slot], ray.origin, ray.direction, t, u, v) &&
                    t < best_t) {
                    best_t = t;
                    t_max_q = t;
                    best_slot = slot;
                    best_u = u;
                    best_v = v;
                }
            }
        } else {
            // Pre-order layout: the left child is the next slot. Test both
            // children and descend into the nearer one first so the hit distance
            // tightens early and prunes the farther subtree. These two loads also
            // supply the descended child's payload, which is why visiting an
            // already-tested child afterwards needs no memory at all.
            const uint left = node_index + 1u;
            const uint right = payload;
            const uint4 left_node = scene.nodes[left];
            const uint4 right_node = scene.nodes[right];
            float entered_left = 0.0f;
            float entered_right = 0.0f;
            const bool hit_left =
                pt_qbox_hit_entered(pt_decode_box(left_node), q.inv_direction,
                                    q.origin_times_inv, q.t_min, t_max_q, entered_left);
            const bool hit_right =
                pt_qbox_hit_entered(pt_decode_box(right_node), q.inv_direction,
                                    q.origin_times_inv, q.t_min, t_max_q, entered_right);
            if (hit_left && hit_right) {
                const bool left_first = entered_left <= entered_right;
                if (stack_size < PT_BVH_STACK_SIZE) {
                    stack[stack_size] = left_first ? right : left;
                    stack_entered[stack_size] = left_first ? entered_right : entered_left;
                    stack_payload[stack_size] = left_first ? right_node.w : left_node.w;
                    ++stack_size;
                }
                node_index = left_first ? left : right;
                payload = left_first ? left_node.w : right_node.w;
                node_tested = true;
                continue;
            } else if (hit_left) {
                node_index = left;
                payload = left_node.w;
                node_tested = true;
                continue;
            } else if (hit_right) {
                node_index = right;
                payload = right_node.w;
                node_tested = true;
                continue;
            }
        }

        // Pop the next deferred subtree. A node pushed as hit stays intersected
        // (its entered/exited interval never changes and entered >= t_min > 0),
        // and the only limit that tightens afterwards is the near-hit distance,
        // so one compare replaces the slab test. Pruned subtrees touch no memory
        // at all; a survivor loads only its 4-byte payload and enters the walk
        // already tested.
        bool resumed = false;
        while (stack_size > 0) {
            --stack_size;
            if (stack_entered[stack_size] <= t_max_q) {
                node_index = stack[stack_size];
                payload = stack_payload[stack_size];
                node_tested = true;
                resumed = true;
                break;
            }
        }
        if (!resumed) {
            break;
        }
    }

    if (best_slot == 0xFFFFFFFFu) {
        return false;
    }
    const device PtTriNormals& nrm = scene.normals[best_slot];
    best_normal = normalize((1.0f - best_u - best_v) * pt_v3(nrm.n0) + best_u * pt_v3(nrm.n1) +
                            best_v * pt_v3(nrm.n2));
    return true;
}

