            }
        } else {
            const uint left = node_index + 1u;
            const uint right = payload;
            const uint4 left_node = scene.nodes[left];
            const uint4 right_node = scene.nodes[right];
            float entered_left = 0.0f;
            float entered_right = 0.0f;
            const bool hit_left =
                pt_qbox_hit_entered(pt_decode_box(left_node), q.inv_direction,
                                    q.origin_times_inv, q.t_min, q.t_max, entered_left);
